import{_ as e,o,c as i,ag as a}from"./chunks/framework.IxO3mcwW.js";const s="/getbiji-docs/images/shortcuts-01.png",r="/getbiji-docs/images/shortcuts-02.png",p="/getbiji-docs/images/shortcuts-03.png",l="/getbiji-docs/images/shortcuts-04.png",f=JSON.parse('{"title":"快捷指令","description":"","frontmatter":{},"headers":[],"relativePath":"efficiency/shortcuts.md","filePath":"efficiency/shortcuts.md","lastUpdated":1773215704000}'),n={name:"efficiency/shortcuts.md"};function c(d,t,h,u,_,m){return o(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="快捷指令" tabindex="-1">快捷指令 <a class="header-anchor" href="#快捷指令" aria-label="Permalink to &quot;快捷指令&quot;">​</a></h1><blockquote><p>效率翻倍，一键触达</p></blockquote><p>将 Get 笔记功能绑定到 iPhone 的实体操作按钮或轻点背面，实现极速启动。</p><h2 id="一、将实体操作按钮设置为快捷指令" tabindex="-1">一、将实体操作按钮设置为快捷指令 <a class="header-anchor" href="#一、将实体操作按钮设置为快捷指令" aria-label="Permalink to &quot;一、将实体操作按钮设置为快捷指令&quot;">​</a></h2><p>如果你的手机是 iPhone 15 Pro 和 iPhone 16 全系列机型，可以将手机的实体操作按钮设置为 Get 笔记相关的快捷指令，设置完成后，长按手机左侧边的操作按钮（原静音按钮）即可快速打开 Get 笔记。</p><p><strong>设置步骤：</strong></p><ol><li><p>🌟 打开系统设置，向上滑动找到&quot;操作按钮&quot;后点击进入</p></li><li><p>🌟 向左滑动找到&quot;快捷指令&quot;后，点击按钮&quot;选取快捷指令&quot;</p></li><li><p>🌟 在顶部搜索框输入&quot;Get笔记&quot;后，可以选择已经添加过的 Siri 快捷指令；你也可以点击&quot;打开App…&quot;，选择 Get 笔记</p></li></ol><h2 id="二、轻点两下或三下-iphone-背面以快速执行操作" tabindex="-1">二、轻点两下或三下 iPhone 背面以快速执行操作 <a class="header-anchor" href="#二、轻点两下或三下-iphone-背面以快速执行操作" aria-label="Permalink to &quot;二、轻点两下或三下 iPhone 背面以快速执行操作&quot;">​</a></h2><p><strong>设置步骤：</strong></p><ol><li><p>🌟 在手机「设置」里，打开「辅助功能」，选择「触控」</p></li><li><p>🌟 在「触控」页面下滑至最底部，点击「轻点背面」</p></li><li><p>🌟 根据个人需求设置「轻点两下」或「轻点三下」，可关联设置为 Get 笔记相关的快捷指令</p></li></ol><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;"><img src="'+s+'" alt="操作按钮设置" style="width:180px;border-radius:8px;"><img src="'+r+'" alt="选取快捷指令" style="width:180px;border-radius:8px;"><img src="'+p+'" alt="搜索Get笔记" style="width:180px;border-radius:8px;"><img src="'+l+'" alt="轻点背面设置" style="width:180px;border-radius:8px;"></div>',12)])])}const q=e(n,[["render",c]]);export{f as __pageData,q as default};
